function validate(input) {
  const [fn, inputs] = input;
  if (fn === null || typeof fn !== 'object' || !['sum', 'list', 'life'].includes(fn.name)) return 'fn.name must be "sum", "list" or "life".';
  if (!Number.isInteger(fn.length) || fn.length < 0 || fn.length > 1000) return 'fn.length must be an integer from 0 to 1000.';
  if (!Array.isArray(inputs) || inputs.length < 1 || inputs.length > 1000) return 'Give 1 to 1000 argument lists.';
  let total = 0;
  for (const args of inputs) {
    if (!Array.isArray(args) || !args.every(v => Number.isInteger(v) && v >= 0 && v <= 100000)) return 'Each argument list holds integers from 0 to 10^5.';
    total += args.length;
  }
  if (total !== fn.length) return `The lists must hold exactly fn.length = ${fn.length} arguments in total.`;
  if (fn.length > 0 && inputs[inputs.length - 1].length === 0) return 'The last argument list must not be empty.';
  if (fn.length === 0 && inputs.length !== 1) return 'When fn.length is 0, inputs must be [[]].';
  return null;
}

