function adapt(input, solve, kit) {
  const [spec, inputs] = input;
  const body = { sum: (args) => args.reduce((total, value) => total + value, 0), list: (args) => args, life: () => 42 }[spec.name];
  let runs = 0;
  const fn = function (...args) {
    runs += 1;
    const result = body(args);
    kit.trace(`${spec.name}(${args.join(', ')}) runs and returns ${JSON.stringify(result)}`);
    return result;
  };
  // fn.length is what curry reads to know how many arguments fn needs.
  Object.defineProperty(fn, 'length', { value: spec.length });
  Object.defineProperty(fn, 'name', { value: spec.name });
  let current = solve(fn);
  if (typeof current !== 'function') throw new Error('curry must return a function.');
  inputs.forEach((args, i) => {
    if (typeof current !== 'function') throw new Error(`Call ${i} returned ${JSON.stringify(current)}, but arguments are still missing, so it should return a function.`);
    current = current(...args);
    kit.trace(`Call ${i + 1} with (${args.join(', ')}) returns ${typeof current === 'function' ? 'a function' : JSON.stringify(current)}`);
  });
  if (typeof current === 'function') throw new Error('Every argument was given, but the last call still returned a function instead of running fn.');
  if (runs !== 1) throw new Error(`fn should run exactly once, but it ran ${runs} times.`);
  return current;
}

