function generate(rand, size) {
  const small = size === 'small';
  const roll = rand();
  const name = roll < 0.45 ? 'sum' : roll < 0.9 ? 'list' : 'life';
  const length = small ? Math.floor(rand() * 5) : 900 + Math.floor(rand() * 101);
  if (length === 0) return [{ name, length }, [[]]];
  const values = Array.from({ length }, () => Math.floor(rand() * (small ? 10 : 100001)));
  const inputs = [];
  let next = 0;
  while (next < length) {
    // At most 1000 calls: the last one takes whatever is left.
    const take = inputs.length === 998 ? length - next : Math.floor(rand() * (small ? 3 : 4));
    inputs.push(values.slice(next, next + take));
    next += take;
  }
  while (inputs[inputs.length - 1].length === 0) inputs.pop();
  return [{ name, length }, inputs];
}
